31	public class DistinctCountCPCSketchValueAggregator implements ValueAggregator<Object, Object> {
32	  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;
33	
34	  private final int _lgK;
35	
36	  public DistinctCountCPCSketchValueAggregator(List<ExpressionContext> arguments) {
37	    // length 1 means we use the Helix default
38	    if (arguments.size() <= 1) {
39	      _lgK = CommonConstants.Helix.DEFAULT_CPC_SKETCH_LGK;
40	    } else {
41	      _lgK = arguments.get(1).getLiteral().getIntValue();
42	    }
43	  }
44	
45	  @Override
46	  public AggregationFunctionType getAggregationType() {
47	    return AggregationFunctionType.DISTINCTCOUNTCPCSKETCH;
48	  }
49	
50	  @Override
51	  public DataType getAggregatedValueType() {
52	    return AGGREGATED_VALUE_TYPE;
53	  }
54	
55	  @Override
56	  public Object getInitialAggregatedValue(Object rawValue) {
57	    CpcUnion cpcUnion = new CpcUnion(_lgK);
58	    if (rawValue instanceof byte[]) { // Serialized Sketch
59	      byte[] bytes = (byte[]) rawValue;
60	      cpcUnion.update(deserializeAggregatedValue(bytes));
61	    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
62	      byte[][] serializedSketches = (byte[][]) rawValue;
63	      for (byte[] bytes : serializedSketches) {
64	        cpcUnion.update(deserializeAggregatedValue(bytes));
65	      }
66	    } else {
67	      CpcSketch pristineSketch = empty();
68	      addObjectToSketch(rawValue, pristineSketch);
69	      cpcUnion.update(pristineSketch);
70	    }
71	    return cpcUnion;
72	  }
73	
74	  @Override
75	  public Object applyRawValue(Object aggregatedValue, Object rawValue) {
76	    CpcUnion cpcUnion = extractUnion(aggregatedValue);
77	    if (rawValue instanceof byte[]) {
78	      byte[] bytes = (byte[]) rawValue;
79	      CpcSketch sketch = deserializeAggregatedValue(bytes);
80	      cpcUnion.update(sketch);
81	    } else {
82	      CpcSketch pristineSketch = empty();
83	      addObjectToSketch(rawValue, pristineSketch);
84	      cpcUnion.update(pristineSketch);
85	    }
86	    return cpcUnion;
87	  }
88	
89	  @Override
90	  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
91	    CpcUnion cpcUnion = extractUnion(aggregatedValue);
92	    CpcSketch sketch = extractSketch(value);
93	    cpcUnion.update(sketch);
94	    return cpcUnion;
95	  }
96	
97	  @Override
98	  public Object cloneAggregatedValue(Object value) {
99	    return deserializeAggregatedValue(serializeAggregatedValue(value));
100	  }
101	
102	  @Override
103	  public int getMaxAggregatedValueByteSize() {
104	    return CpcSketch.getMaxSerializedBytes(_lgK);
105	  }
106	
107	  @Override
108	  public byte[] serializeAggregatedValue(Object value) {
109	    CpcSketch sketch = extractSketch(value);
110	    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.serialize(sketch);
111	  }
112	
113	  @Override
114	  public CpcSketch deserializeAggregatedValue(byte[] bytes) {
115	    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.deserialize(bytes);
116	  }
117	
118	  private CpcSketch union(CpcSketch left, CpcSketch right) {
119	    if (left == null && right == null) {
120	      return empty();
121	    } else if (left == null) {
122	      return right;
123	    } else if (right == null) {
124	      return left;
125	    }
126	
127	    CpcUnion union = new CpcUnion(_lgK);
128	    union.update(left);
129	    union.update(right);
130	    return union.getResult();
131	  }
132	
133	  private void addObjectToSketch(Object rawValue, CpcSketch sketch) {
134	    if (rawValue instanceof String) {
135	      sketch.update((String) rawValue);
136	    } else if (rawValue instanceof Integer) {
137	      sketch.update((Integer) rawValue);
138	    } else if (rawValue instanceof Long) {
139	      sketch.update((Long) rawValue);
140	    } else if (rawValue instanceof Double) {
141	      sketch.update((Double) rawValue);
142	    } else if (rawValue instanceof Float) {
143	      sketch.update((Float) rawValue);
144	    } else if (rawValue instanceof Object[]) {
145	      addObjectsToSketch((Object[]) rawValue, sketch);
146	    } else {
147	      throw new IllegalStateException(
148	          "Unsupported data type for CPC Sketch aggregation: " + rawValue.getClass().getSimpleName());
149	    }
150	  }
151	
152	  private void addObjectsToSketch(Object[] rawValues, CpcSketch sketch) {
153	    if (rawValues instanceof String[]) {
154	      for (String s : (String[]) rawValues) {
155	        sketch.update(s);
156	      }
157	    } else if (rawValues instanceof Integer[]) {
158	      for (Integer i : (Integer[]) rawValues) {
159	        sketch.update(i);
160	      }
161	    } else if (rawValues instanceof Long[]) {
162	      for (Long l : (Long[]) rawValues) {
163	        sketch.update(l);
164	      }
165	    } else if (rawValues instanceof Double[]) {
166	      for (Double d : (Double[]) rawValues) {
167	        sketch.update(d);
168	      }
169	    } else if (rawValues instanceof Float[]) {
170	      for (Float f : (Float[]) rawValues) {
171	        sketch.update(f);
172	      }
173	    } else {
174	      throw new IllegalStateException(
175	          "Unsupported data type for CPC Sketch aggregation: " + rawValues.getClass().getSimpleName());
176	    }
177	  }
178	
179	  private CpcUnion extractUnion(Object value) {
180	    if (value == null) {
181	      return new CpcUnion(_lgK);
182	    } else if (value instanceof CpcUnion) {
183	      return (CpcUnion) value;
184	    } else if (value instanceof CpcSketch) {
185	      CpcSketch sketch = (CpcSketch) value;
186	      CpcUnion cpcUnion = new CpcUnion(_lgK);
187	      cpcUnion.update(sketch);
188	      return cpcUnion;
189	    } else {
190	      throw new IllegalStateException(
191	          "Unsupported data type for CPC Sketch aggregation: " + value.getClass().getSimpleName());
192	    }
193	  }
