109	  /**
110	   * Returns the maximum number of storage bytes required for a Compact Integer Tuple Sketch with the given
111	   * number of actual entries. Note that this assumes the worst case of the sketch in
112	   * estimation mode, which requires storing theta and count.
113	   * @return the maximum number of storage bytes required for a Compact Integer Tuple Sketch with the given number
114	   * of entries.
115	   */
116	  @Override
117	  public int getMaxAggregatedValueByteSize() {
118	    if (_nominalEntries == 0) {
119	      return 8;
120	    }
121	    if (_nominalEntries == 1) {
122	      return 16;
123	    }
124	    int longSizeInBytes = Long.BYTES;
125	    int intSizeInBytes = Integer.BYTES;
126	    return (_nominalEntries * (longSizeInBytes + intSizeInBytes)) + 24;
127	  }
