129	  @Override
130	  public byte[] serializeAggregatedValue(Object value) {
131	    Sketch sketch = extractSketch(value);
132	    return sketch.compact().toByteArray();
133	  }
134	
135	  @Override
136	  public Sketch<IntegerSummary> deserializeAggregatedValue(byte[] bytes) {
137	    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(bytes);
138	  }
